Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
using System.Collections.Generic;
public class WinEnum {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
  [DllImport("user32.dll")] public static extern int GetWindowTextLength(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
  [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
  [DllImport("user32.dll")] public static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
}
"@

$results = New-Object System.Collections.Generic.List[object]
[WinEnum]::EnumWindows({
  param($hWnd, $lParam)
  $pid = 0
  [void][WinEnum]::GetWindowThreadProcessId($hWnd, [ref]$pid)
  try { $proc = Get-Process -Id $pid -ErrorAction Stop } catch { return $true }
  if ($proc.ProcessName -notmatch '^(chrome|msedge|brave)$') { return $true }
  $len = [WinEnum]::GetWindowTextLength($hWnd)
  $sb = New-Object System.Text.StringBuilder ($len + 1)
  [void][WinEnum]::GetWindowText($hWnd, $sb, $sb.Capacity)
  $cls = New-Object System.Text.StringBuilder 256
  [void][WinEnum]::GetClassName($hWnd, $cls, $cls.Capacity)
  $rect = New-Object WinEnum+RECT
  [void][WinEnum]::GetWindowRect($hWnd, [ref]$rect)
  $visible = [WinEnum]::IsWindowVisible($hWnd)
  $iconic = [WinEnum]::IsIconic($hWnd)
  $w = $rect.Right - $rect.Left; $h = $rect.Bottom - $rect.Top
  if ($visible -or $len -gt 0 -or ($w -gt 0 -and $h -gt 0)) {
    $results.Add([PSCustomObject]@{
      HWnd = [int64]$hWnd
      Pid = $pid
      Process = $proc.ProcessName
      Visible = $visible
      Iconic = $iconic
      Class = $cls.ToString()
      Title = $sb.ToString()
      W = $w; H = $h
      Left = $rect.Left; Top = $rect.Top
    }) | Out-Null
  }
  return $true
}, [IntPtr]::Zero) | Out-Null

$results | Sort-Object Visible -Descending | Format-Table -AutoSize
Write-Host ("Window count: " + $results.Count)

Get-CimInstance Win32_Process -Filter "ProcessId = 16548" | Select-Object ProcessId, Name, ParentProcessId, CommandLine | Format-List; Write-Host '---PARENT OF 16548---'; $p = Get-CimInstance Win32_Process -Filter "ProcessId = 16548" -ErrorAction SilentlyContinue; if ($p) { Get-CimInstance Win32_Process -Filter "ProcessId = $($p.ParentProcessId)" -ErrorAction SilentlyContinue | Select ProcessId, Name, CommandLine | Format-List }

