function Get-SasChromeDescendants {
    param(
        [Parameter(Mandatory = $true)][int]$RootPid,
        [Parameter(Mandatory = $true)]$TreeMap
    )

    $ordered = New-Object System.Collections.Generic.List[object]
    $queue = New-Object System.Collections.Generic.Queue[int]
    $seen = New-Object 'System.Collections.Generic.HashSet[int]'
    $queue.Enqueue($RootPid) | Out-Null
    [void]$seen.Add($RootPid)

    while ($queue.Count -gt 0) {
        $current = $queue.Dequeue()
        if (-not $TreeMap.ByParent.ContainsKey($current)) { continue }
        foreach ($child in $TreeMap.ByParent[$current]) {
            $childPid = [int]$child.ProcessId
            if ($seen.Add($childPid)) {
                $ordered.Add($child) | Out-Null
                $queue.Enqueue($childPid) | Out-Null
            }
        }
    }

    return @($ordered)
}

