using System; using System.Text; using System.Runtime.InteropServices; using System.Collections.Generic;
public class WinEnum6 {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc cb, IntPtr lp);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern int GetWindowTextLength(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
  [DllImport("user32.dll")] public static extern int GetClassName(IntPtr hWnd, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT r);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L; public int T; public int R; public int B; }
}
"@
$rows=[System.Collections.Generic.List[object]]::new()
[WinEnum6]::EnumWindows({
  param($h,$lp)
  if(-not [WinEnum6]::IsWindowVisible($h)){return $true}
  $r=New-Object WinEnum6+RECT; [void][WinEnum6]::GetWindowRect($h,[ref]$r)
  $w=$r.R-$r.L; $ht=$r.B-$r.T
  # large blank-looking candidates on primary-ish coords
  if($w -lt 400 -or $ht -lt 400){return $true}
  [uint32]$procId=0; [void][WinEnum6]::GetWindowThreadProcessId($h,[ref]$procId)
  $len=[WinEnum6]::GetWindowTextLength($h)
  $sb=New-Object Text.StringBuilder ($len+1); if($len -gt 0){[void][WinEnum6]::GetWindowText($h,$sb,$sb.Capacity)}
  $cls=New-Object Text.StringBuilder 256; [void][WinEnum6]::GetClassName($h,$cls,$cls.Capacity)
  $p=Get-Process -Id ([int]$procId) -EA SilentlyContinue
  $rows.Add([pscustomobject]@{Pid=[int]$procId; Process=$p.ProcessName; Class=$cls.ToString(); Title=$sb.ToString(); L=$r.L;T=$r.T;W=$w;H=$ht})|Out-Null
  return $true
},[IntPtr]::Zero)|Out-Null
$rows | Sort-Object W -Descending | Format-Table -AutoSize
