            Title = $props.Title
            Artist = $props.Artist
            Album = $props.AlbumTitle
            PlaybackStatus = $playback.PlaybackStatus
            Controls = ($playback.Controls | Out-String).Trim()
        }
    } | Format-List
}
catch {
    Write-Host ("SMTC_FAILED: " + $_.Exception.Message)
}

Write-Host ''
Write-Host '=== WASAPI SESSIONS WITH PEAK ==='
$wasapi = @'
using System;
using System.Runtime.InteropServices;
using System.Collections.Generic;

public static class SasWasapiPeak {
  [ComImport, Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")]
  class MMDeviceEnumeratorComObject { }

  [Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IMMDeviceEnumerator {
    int NotImpl1();
    [PreserveSig] int GetDefaultAudioEndpoint(int dataFlow, int role, out IMMDevice ppDevice);
  }

  [Guid("D666063F-1587-4E43-81F1-B948E807363F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IMMDevice {
    [PreserveSig] int Activate(ref Guid iid, int dwClsCtx, IntPtr pActivationParams, [MarshalAs(UnmanagedType.IUnknown)] out object ppInterface);
  }

  [Guid("77AA99A0-1BD6-484F-8BC7-2C654C9A9B6F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioSessionManager2 {
    int NotImpl1();
    int NotImpl2();
    [PreserveSig] int GetSessionEnumerator(out IntPtr SessionEnum);
  }

  [Guid("E2F5BB11-0570-40CA-ACDD-3AA012B80965"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioSessionEnumerator {
    [PreserveSig] int GetCount(out int SessionCount);
    [PreserveSig] int GetSession(int SessionCount, out IntPtr Session);
  }

  [Guid("F4B1A599-7266-4319-A8CA-E70ACB11E8CD"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioSessionControl {
    [PreserveSig] int GetState(out int pRetVal);
    int NotImpl2();
    [PreserveSig] int GetDisplayName([MarshalAs(UnmanagedType.LPWStr)] out string pRetVal);
  }

  [Guid("BFB7FF88-7238-4FC9-8FA9-3B24BC4C5E5A"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioSessionControl2 {
    int NotImpl1();
    int NotImpl2();
    int NotImpl3();
    int NotImpl4();
    int NotImpl5();
    int NotImpl6();
    int NotImpl7();
    int NotImpl8();
    int NotImpl9();
    [PreserveSig] int GetSessionIdentifier([MarshalAs(UnmanagedType.LPWStr)] out string pRetVal);
    [PreserveSig] int GetSessionInstanceIdentifier([MarshalAs(UnmanagedType.LPWStr)] out string pRetVal);
    [PreserveSig] int GetProcessId(out UInt32 pRetVal);
    [PreserveSig] int IsSystemSoundsSession();
  }

  [Guid("C02216F6-8C67-4B5B-9D00-D008E73E0064"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
  interface IAudioMeterInformation {
    [PreserveSig] int GetPeakValue(out float pfPeak);
  }

  public static List<string> List() {
    var rows = new List<string>();
    var enumerator = (IMMDeviceEnumerator)(new MMDeviceEnumeratorComObject());
    IMMDevice device;
    Marshal.ThrowExceptionForHR(enumerator.GetDefaultAudioEndpoint(0, 0, out device));
    Guid iidMgr = typeof(IAudioSessionManager2).GUID;
    object o;
    Marshal.ThrowExceptionForHR(device.Activate(ref iidMgr, 23, IntPtr.Zero, out o));
    var mgr = (IAudioSessionManager2)o;
    IntPtr enumPtr;
    Marshal.ThrowExceptionForHR(mgr.GetSessionEnumerator(out enumPtr));
    var sessionEnum = (IAudioSessionEnumerator)Marshal.GetObjectForIUnknown(enumPtr);
    int count;
    Marshal.ThrowExceptionForHR(sessionEnum.GetCount(out count));
    for (int i = 0; i < count; i++) {
      IntPtr ctlPtr;
      Marshal.ThrowExceptionForHR(sessionEnum.GetSession(i, out ctlPtr));
      var ctl = (IAudioSessionControl)Marshal.GetObjectForIUnknown(ctlPtr);
      var ctl2 = (IAudioSessionControl2)ctl;
      var meter = ctl as IAudioMeterInformation;
      int state;
      ctl.GetState(out state);
      string display;
      ctl.GetDisplayName(out display);
      string id, iid;
      uint pid;
      ctl2.GetSessionIdentifier(out id);
      ctl2.GetSessionInstanceIdentifier(out iid);
      ctl2.GetProcessId(out pid);
