from __future__ import annotations

from comtypes import CLSCTX_ALL
from pycaw.pycaw import (
    AudioUtilities,
    IAudioMeterInformation,
    IAudioSessionControl2,
    IAudioSessionManager2,
    ISimpleAudioVolume,
)


def silence_device(device) -> None:
    name = getattr(device, "FriendlyName", "?")
    print(f"=== {name} ===")
    try:
        manager = device._dev.Activate(IAudioSessionManager2._iid_, CLSCTX_ALL, None)
        manager = manager.QueryInterface(IAudioSessionManager2)
    except Exception as e:
        print(f"activate_failed: {e}")
        return
    enumerator = manager.GetSessionEnumerator()
    for i in range(enumerator.GetCount()):
        control = enumerator.GetSession(i)
        control2 = control.QueryInterface(IAudioSessionControl2)
        try:
            pid = int(control2.GetProcessId())
        except Exception:
            continue
        proc_name = "?"
        try:
            import psutil

            proc_name = psutil.Process(pid).name()
        except Exception:
            pass
        if proc_name.lower() != "cursor.exe":
            continue
        try:
            vol = control.QueryInterface(ISimpleAudioVolume)
            before_mute = bool(vol.GetMute())
            before_level = float(vol.GetMasterVolume())
            vol.SetMasterVolume(0.0, None)
            vol.SetMute(1, None)
            after_mute = bool(vol.GetMute())
            after_level = float(vol.GetMasterVolume())
            peak = 0.0
            try:
                peak = float(control.QueryInterface(IAudioMeterInformation).GetPeakValue())
            except Exception:
                pass
            print(
                f"SILENCED pid={pid} mute {before_mute}->{after_mute} "
                f"level {before_level:.3f}->{after_level:.3f} peak_now={peak:.4f}"
            )
        except Exception as e:
            print(f"FAIL pid={pid}: {e}")


def main() -> None:
    for d in AudioUtilities.GetAllDevices():
        try:
            state = str(d.state)
            name = d.FriendlyName or ""
        except Exception:
            continue
        if "Active" not in state:
            continue
        if "SineAudio" in name or "Headphone" in name or "Cursor" in name:
            silence_device(d)
    # also default sessions
    print("=== DEFAULT SESSIONS CURSOR ===")
    for s in AudioUtilities.GetAllSessions():
        try:
            if not s.Process or s.Process.name().lower() != "cursor.exe":
                continue
        except Exception:
            continue
        try:
            vol = s._ctl.QueryInterface(ISimpleAudioVolume)
            vol.SetMasterVolume(0.0, None)
            vol.SetMute(1, None)
            print(f"default silenced pid={s.Process.pid}")
        except Exception as e:
            print(f"default fail: {e}")


if __name__ == "__main__":
    main()

