from __future__ import annotations

"""Close/stop audible Cursor media. Never treat mute as success."""

from comtypes import CLSCTX_ALL
from pycaw.pycaw import (
    AudioUtilities,
    IAudioMeterInformation,
    IAudioSessionControl2,
    IAudioSessionManager2,
    ISimpleAudioVolume,
)


def unmute_and_report() -> list[tuple[int, float]]:
    """Restore Cursor session levels, then report peaking PIDs."""
    peaking: list[tuple[int, float]] = []
    for d in AudioUtilities.GetAllDevices():
        try:
            name = d.FriendlyName or ""
            state = str(d.state)
        except Exception:
            continue
        if "Active" not in state:
            continue
        if "SineAudio" not in name and "Headphone" not in name:
            continue
        try:
            mgr = d._dev.Activate(
                IAudioSessionManager2._iid_, CLSCTX_ALL, None
            ).QueryInterface(IAudioSessionManager2)
        except Exception as e:
            print(f"activate_failed {name}: {e}")
            continue
        en = mgr.GetSessionEnumerator()
        for i in range(en.GetCount()):
            ctl = en.GetSession(i)
            ctl2 = ctl.QueryInterface(IAudioSessionControl2)
            try:
                pid = int(ctl2.GetProcessId())
            except Exception:
                continue
            import psutil

            try:
                proc_name = psutil.Process(pid).name()
            except Exception:
                proc_name = "?"
            if proc_name.lower() != "cursor.exe":
                continue
            vol = ctl.QueryInterface(ISimpleAudioVolume)
            # Undo band-aid mute/volume clamp.
            vol.SetMute(0, None)
            vol.SetMasterVolume(1.0, None)
            peak = float(ctl.QueryInterface(IAudioMeterInformation).GetPeakValue())
            print(
                f"UNMUTED Cursor headphones pid={pid} mute={vol.GetMute()} "
                f"level={vol.GetMasterVolume():.3f} peak={peak:.4f}"
            )
            if peak > 0.001:
                peaking.append((pid, peak))
    return peaking


def main() -> None:
    peaking = unmute_and_report()
    print(f"peaking_count={len(peaking)}")


if __name__ == "__main__":
    main()
